from __future__ import annotations

from urllib.parse import quote


_THERAPEUTIC_PLACEHOLDER = "Раздел будет дополнен по вашей PDF-базе масел."
_HISTORY_PLACEHOLDER = "Исторические сведения будут дополнены по вашей PDF-базе масел."
_DEFAULT_QUESTIONS = (
    "Какая тема этого масла сейчас наиболее откликается?\n"
    "Где в вашей жизни не хватает этого ресурса?\n"
    "Что меняется, если посмотреть на ситуацию через ресурс этого масла?"
)
_DEFAULT_RESOURCE_MINUS = "В минусе поднимаются темы, противоположные ресурсам этого масла."


def _normalize(value: str) -> str:
    return " ".join(value.lower().replace("ё", "е").replace('"', "").split())


def _source_image(source_type: str, title: str) -> str:
    palette = {
        "citrus": ("#f6a623", "#ffe3a1", "цитрус"),
        "flower": ("#d36a8b", "#f6d5de", "цветок"),
        "tree": ("#5e7d3a", "#d7e5b8", "дерево"),
        "resin": ("#8a5a3c", "#e4c9b0", "смола"),
        "spice": ("#b56134", "#f0cfb8", "специя"),
        "herb": ("#5d8c63", "#d7edd9", "трава"),
        "grass": ("#4f8b57", "#d4ecd7", "трава"),
    }
    primary, secondary, label = palette.get(source_type, palette["herb"])
    svg = f"""
    <svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 640 420'>
      <defs>
        <linearGradient id='g' x1='0' x2='1' y1='0' y2='1'>
          <stop offset='0%' stop-color='{secondary}' />
          <stop offset='100%' stop-color='#fffaf4' />
        </linearGradient>
      </defs>
      <rect width='640' height='420' rx='32' fill='url(#g)' />
      <circle cx='510' cy='86' r='54' fill='{primary}' fill-opacity='0.16' />
      <circle cx='118' cy='330' r='80' fill='{primary}' fill-opacity='0.11' />
      <rect x='54' y='58' width='220' height='34' rx='17' fill='{primary}' fill-opacity='0.18' />
      <text x='74' y='81' font-size='18' font-family='Arial' fill='{primary}'>{label}</text>
      <text x='54' y='196' font-size='46' font-family='Arial' font-weight='700' fill='#2d241e'>{title}</text>
      <text x='54' y='244' font-size='22' font-family='Arial' fill='#6a5a4a'>Источник сырья для эфирного масла</text>
      <path d='M470 286c-45-79-133-118-219-98 61 8 120 44 159 99H220v37h248c31 0 41-20 34-38l-32-70Z' fill='{primary}' fill-opacity='0.8' />
    </svg>
    """.strip()
    return f"data:image/svg+xml;charset=UTF-8,{quote(svg)}"


def _card(
    *,
    slug: str,
    name: str,
    source_type: str,
    description: str,
    questions: str = "",
    aliases: tuple[str, ...] = (),
    volatility: str = "Средняя",
    resource_minus: str = "",
    therapeutic: str = "",
    history: str = "",
) -> dict[str, object]:
    prompt = questions.strip() or _DEFAULT_QUESTIONS
    plus = description.strip()
    minus = resource_minus.strip() or _DEFAULT_RESOURCE_MINUS
    return {
        "slug": slug,
        "name": name,
        "aliases": list(aliases),
        "description": description.strip(),
        "questions": prompt,
        "nps_effect": f"По текущей эмоциональной базе масло связано с темами: {description.strip()}",
        "therapeutic_properties": therapeutic.strip() or _THERAPEUTIC_PLACEHOLDER,
        "psychological_properties": description.strip(),
        "resource_values": {"plus": plus, "minus": minus},
        "history": history.strip() or _HISTORY_PLACEHOLDER,
        "volatility": volatility,
        "image_url": _source_image(source_type, name),
        "image_alt": f"{name}: источник сырья",
    }


